const pad=n=>String(n).padStart(2,"0"),ymd=t=>{const d=new Date(t);return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate())},uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const DEF=()=>({name:"",key:"",model:"claude-sonnet-5-5",tone:"jarvis",ok:false,tasks:[],log:[],excuses:[],chat:[],focus:null,ntfy:"",dsch:"",ej:{s:"",t:"",k:""},people:[],contract:null,hist:[],pen:["20 pushups","One hour without your phone","Cold shower tonight"],lang:"en-IN",auto:true,cc:"91",alog:[],snitch:false,chatM:[],sos:null,rs:null,rd:[],rc:{},pp:null});
