/* ---- stats ---- */
const open=()=>S.tasks.filter(t=>!t.done),late=t=>!t.done&&t.due&&t.due<Date.now();
function streak(){const ds=new Set(S.tasks.filter(t=>t.done).map(t=>ymd(t.doneAt)));let d=Date.now(),n=0;if(!ds.has(ymd(d)))d-=864e5;while(ds.has(ymd(d))){n++;d-=864e5}return n}
function rate(){const w=Date.now()-7*864e5,D=S.tasks.filter(t=>t.done&&t.doneAt>w),k=D.filter(t=>!t.due||t.doneAt<=t.due).length,l=D.length-k+S.tasks.filter(t=>late(t)&&t.created>w).length;return k+l?Math.round(k/(k+l)*100):null}
