function rel(ms){const m=Math.round((ms-Date.now())/6e4),a=Math.abs(m),u=a>=1440?Math.round(a/1440)+"d":a>=60?Math.round(a/60)+"h":a+"m";return m<0?"overdue by "+u:"due in "+u}
