function drainNative(){if(!N||!N.drainLog)return;N.drainLog().then(r=>{const it=(r&&r.items)||[];if(!it.length)return;it.forEach(x=>S.alog.push({t:x.t,ty:x.ty,tx:x.tx}));S.alog.sort((a,b)=>b.t-a.t);S.alog=S.alog.slice(0,150);save();if(ui.tab=="report")render()}).catch(()=>{})}
const nextUp=()=>open().sort((a,b)=>(late(b)-late(a))||(b.pri-a.pri)||((a.due||9e15)-(b.due||9e15)))[0];
/* ---- integrity, contract and analytics engine ---- */
const broken=()=>{let n=0;for(let i=S.hist.length-1;i>=0&&S.hist[i].kept<S.hist[i].total;i--)n++;return n};
const cstreak=()=>{let n=0;for(let i=S.hist.length-1;i>=0&&S.hist[i].total&&S.hist[i].kept==S.hist[i].total;i--)n++;return n};
function integrity(){const w=Date.now()-14*864e5,C=S.hist.filter(h=>h.t>w),ct=C.reduce((a,h)=>a+h.total,0),ck=C.reduce((a,h)=>a+h.kept,0),r=rate(),fm=Math.min(1,S.log.filter(l=>l.type=="focus"&&l.d>w).reduce((a,l)=>a+l.mins,0)/420),q=S.log.filter(l=>l.type=="quit"&&l.d>w).length;
 return Math.max(0,Math.min(100,Math.round((ct?ck/ct:.4)*50+(r==null?.4:r/100)*30+fm*20-q*3)))}
const grade=n=>n>=85?"A":n>=70?"B":n>=55?"C":n>=40?"D":"F";
const hours=()=>{const h=Array(24).fill(0);S.tasks.forEach(t=>{if(t.done&&t.doneAt>Date.now()-30*864e5)h[new Date(t.doneAt).getHours()]++});return h};
const aging=()=>open().map(t=>({t,d:Math.floor((Date.now()-t.created)/864e5)})).filter(x=>x.d>=1).sort((a,b)=>b.d-a.d).slice(0,5);
function excuseWords(){const c={},stop=/^(this|that|with|have|just|then|they|them|from|what|when|will|would|been|only|because|about|there|were|your|more|some|feel|felt|really|very|much|want|dont|didnt|cant)$/;S.excuses.forEach(e=>e.r.toLowerCase().replace(/[^a-z\s]/g," ").split(/\s+/).forEach(w=>{if(w.length>3&&!stop.test(w))c[w]=(c[w]||0)+1}));return Object.entries(c).sort((a,b)=>b[1]-a[1]).slice(0,3)}
function settleDo(c){const T=c.ids.map(id=>S.tasks.find(t=>t.id==id)).filter(Boolean),kept=T.filter(t=>t.done&&ymd(t.doneAt)<=c.date).length,tot=T.length,b=S.people.find(p=>p.buddy);c.settled=true;
 if(tot&&kept==tot){c.res=`All ${tot} kept. Do it again tomorrow.`}else{const p=S.pen[Math.floor(Math.random()*S.pen.length)]||"Write down why you failed";c.res=`Broke ${tot-kept} of ${tot}. Penalty: ${p}.`;if(b&&b.tel)c.confess=`sms:${b.tel}?body=${encodeURIComponent("I failed my contract today ("+T.filter(t=>!t.done).map(t=>t.t).join(", ")+"). My penalty: "+p+". Hold me to it.")}`;c.cname=b?b.name:""}
 S.hist.push({d:c.date,t:Date.now(),kept,total:tot});save()}
const rollover=()=>{if(S.contract&&S.contract.date<ymd(Date.now())&&!S.contract.settled)settleDo(S.contract)};
