 if(c.k=="brief"){ui.act=null;ui.cmd="";ui.tab="scholar";ui.sch="pulse";render();return TM.fire("scholar:brief")}
 if(c.k=="focus"){ui.act=null;ui.cmd="";const t=nextUp();if(!t){toast("Add a task first.");return render()}return A.focus(t.id)}
