/* ---- offline lines (used when there is no API key) ---- */
const LINES={jarvis:["Shall we? One small step now keeps the day in your favour.","A gentle reminder: the list will not shorten itself, but ten minutes will help.","Your calendar and your intentions seem to have drifted. Let us reconcile them.","Might I suggest starting with the smallest overdue item?"],brutal:["Overdue. Again. Your future self is not impressed.","Nobody is coming to do this for you. Start the timer.","You do not lack time, you lack the nerve to start. Ten minutes. Go.","Scrolling will not finish that task. Open it now."],firm:["You have overdue work. Pick one and start.","Small start, right now. Ten minutes.","Decide, then do. The list will not shrink itself.","Stop planning. Begin."]};
