const verdict=()=>{const o=open(),l=o.filter(late).length;return l?`${l} overdue. ${line()}`:o.length?"Clock is ticking. Pick one task and start it.":"An empty list means you are either done or hiding. Add the real work."};
/* ---- AI (your own Anthropic key, called straight from this phone) ---- */
function SYS(){const c=S.contract&&S.contract.date==ymd(Date.now())?S.contract.ids.map(id=>(S.tasks.find(t=>t.id==id)||{}).t).filter(Boolean).join("; "):"none signed";const o=open().map(t=>`- ${t.t} [${["low","high","MUST"][t.pri]}] ${t.due?(late(t)?"OVERDUE, was due ":"due ")+new Date(t.due).toLocaleString():"no deadline"}`).join("\n")||"(none)";
 return`You are Taskmaster, ${S.name}'s personal assistant and accountability coach. Tone: ${S.tone=="brutal"?"brutally honest, blunt, zero coddling, sharp about excuses":"firm, direct and no-nonsense"}. Attack excuses and avoidance, never the person's worth, body, identity or family, and no slurs. Keep replies short and action-first, and end with one concrete step they can start in the next 10 minutes. You can draft texts, emails, call scripts, plans and songs, but you cannot place calls or send anything yourself: the user taps the buttons in the app. If the user seems genuinely distressed, drop the tough act, respond warmly, and suggest talking to someone they trust. Now: ${new Date().toLocaleString()}. Open tasks:\n${o}\nEscalation level ${Math.min(5,broken()+1)} of 5 (raise your intensity as it rises). Contract today: ${c}. Integrity ${integrity()}/100. Streak: ${streak()} days. On-time rate: ${rate()==null?"unknown":rate()+"%"}. Recent excuses: ${S.excuses.slice(0,3).map(e=>e.r).join("; ")||"none"}.`}
async function ai(messages,system,max){const sys=system||(window.TM&&TM.sysDefault?TM.sysDefault():SYS());
 if(!S.key){const r=await fetch("https://text.pollinations.ai/openai",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({model:"openai",messages:[{role:"system",content:sys}].concat(messages),max_tokens:max||1000})});if(!r.ok)throw new Error("The free AI engine is busy ("+r.status+"). Try again in a minute, or add an Anthropic key in Me.");const j=await r.json();return String(j.choices&&j.choices[0]&&j.choices[0].message.content||"").trim()||Promise.reject(new Error("Empty reply, try again."))}
 const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"content-type":"application/json","x-api-key":S.key,"anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},body:JSON.stringify({model:S.model,max_tokens:max||1000,system:sys,messages})});
 const j=await r.json();if(!r.ok)throw new Error(j.error&&j.error.message||"Error "+r.status);return j.content.map(c=>c.text||"").join("").trim()}
const errMsg=e=>"AI error: "+(e.message=="Failed to fetch"?"no connection to the AI engine":e.message);
/* ---- phone alerts that work with the app closed: scheduled pushes via ntfy.sh ---- */
const NT="https://ntfy.sh/",STEPS=[[0,"Time is up on"],[10,"10 minutes late:"],[30,"30 minutes late:"],[60,"An hour late:"],[120,"Two hours late:"]];
async function push(seq,body,o){if(N){try{await N.schedule({id:String(seq),at:Math.round(o.at),title:o.title||"Taskmaster",body,prio:o.p||4,kind:o.kind||"notify",tel:o.tel||"",tels:o.tels||"",callTel:o.callTel||""});return true}catch(e){return false}}if(!S.ntfy)return false;const h={Delay:String(Math.floor(o.at/1e3)),Title:o.title||"Taskmaster",Priority:String(o.p||4),Tags:o.tags||"hourglass"};if(o.act)h.Actions=o.act;if(location.protocol.startsWith("http"))h.Click=location.href.split("#")[0];
 try{return(await fetch(NT+S.ntfy+"/"+encodeURIComponent(seq),{method:"POST",headers:h,body})).ok}catch(e){return false}}
const unpush=q=>N?N.cancel({id:String(q)}).catch(()=>{}):S.ntfy&&fetch(NT+S.ntfy+"/"+encodeURIComponent(q),{method:"DELETE"}).catch(()=>{});
function alertsFor(t){if(!(N||S.ntfy)||t.done||!t.due)return;STEPS.forEach(([m,a],i)=>{const at=t.due+m*6e4;if(at>Date.now()+2e4&&at<Date.now()+(N?400:71)*36e5)push(t.id+"-"+i,`${a} "${t.t}". ${line()}`,{at,title:i?"Overdue":"Due now",p:i>2?5:4,tags:i?"rotating_light":"alarm_clock"})});const b=S.people.find(p=>p.buddy&&p.tel);if(N&&S.snitch&&b&&(t.pri==2||t.stake)){const at=t.due+120*6e4;if(at>Date.now()+2e4)push(t.id+"-snitch","Automated message from "+S.name+"'s Taskmaster app: "+S.name+" missed a deadline: \""+t.t+"\". They asked me to tell you so you can hold them to it.",{at,title:"Snitch sent",kind:"sms",tel:b.tel})}t.sch=Date.now()}
const cancelAlerts=id=>{STEPS.forEach((_,i)=>unpush(id+"-"+i));unpush(id+"-snitch")};
function daily(){if(!(N||S.ntfy)||S.dsch==ymd(Date.now()))return;S.dsch=ymd(Date.now());for(let d=0;d<(N?14:3);d++)[[9,"Morning. Sign today's contract: three non-negotiables. No scrolling first."],[13,"Midday check. Which contract item are you on? Open the app and report."],[17,"Five o'clock. Contract items still open? Fix it now."],[20,"Evening. What did you actually finish today? Open the app and be honest."]].forEach(([h,m])=>{const x=new Date();x.setDate(x.getDate()+d);x.setHours(h,0,0,0);if(x.getTime()>Date.now()+2e4)push("daily-"+ymd(x.getTime())+"-"+h,m,{at:x.getTime(),title:h<12?"Sign your contract":h<20?"Check in":"Settle your day",tags:"memo"})});save()}
function syncAlerts(){if(!(N||S.ntfy))return;S.tasks.forEach(t=>{if(!t.done&&t.due>Date.now()&&(!t.sch||Date.now()-t.sch>30*36e5))alertsFor(t)});daily();save()}
